};
scwin.onpageunload = function() {};
scwin.selectbox1_onchange = function() {
    switch1.setSelectedIndex(selectbox1.getSelectedIndex());
};
scwin.trigger2_onclick = function(e) {
    switch1.insert(textarea1.getValue(), {
        "selected": true
    });
    selectbox1.setSelectedIndex(switch1.getSelectedIndex());
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
